theme.templates/test.liquid:
{% stylesheet %}
  .button {
    background-color: blue;
    color: white;
    padding: 10px 20px;
  }
{% endstylesheet %}

{% javascript %}
  function greet(name) {
    console.log('Hello, ' + name + '!');
  }
  greet('World');
{% endjavascript %}

{% stylesheet %}
  .button {
    background-color: {{ settings.button_color }};
    color: white;
  }
{% endstylesheet %}

{% javascript %}
  const apiUrl = '{{ shop.url }}';
  fetch(apiUrl);
{% endjavascript %}

{% stylesheet %}
  .button {
    {% if settings.enable_hover %}
      background-color: blue;
    {% endif %}
  }
{% endstylesheet %}

{% javascript %}
  {% if settings.enable_analytics %}
    console.log('Analytics enabled');
  {% endif %}
{% endjavascript %}

{% stylesheet %}
  .button {
    background-color: {{ settings.button_color }};
    {% if settings.show_border %}
      border: 1px solid {{ settings.border_color }};
    {% endif %}
  }
{% endstylesheet %}

{% stylesheet %}
  /* This should trigger an error */
  {% raw %}
    .nested { color: red; }
  {% endraw %}
{% endstylesheet %}
